<script setup lang="ts">
import {computed,h} from 'vue';import type {Workbench} from '../app/useWorkbench';import JsonReport from '../shared/JsonReport.vue';
const {w}=defineProps<{w:Workbench}>();const s=w.s;
const groups=computed(()=>{const search=s.paramSearch.trim().toLowerCase();return (s.params?.groups||[]).map((g:any)=>({...g,rows:g.rows.filter((p:any)=>(s.paramScope==='all'||p.recommended!==false&&(s.paramScope!=='active'||p.classification!=='unclassified'&&p.usage?.active!==false))&&(!search||[p.name,p.label,p.desc,s.paramValues[p.name]].some(v=>String(v||'').toLowerCase().includes(search))))})).filter((g:any)=>g.rows.length);});
const rowCount=computed(()=>groups.value.reduce((n:number,g:any)=>n+g.rows.length,0));
const columns=computed(()=>{const headers=s.csv?.header_rows||[s.csv?.header_zh||[],s.csv?.header_en||[]];const width=Math.max(0,...headers.map((row:string[])=>row.length),s.csv?.rows?.[0]?.length||0);return Array.from({length:width},(_,index)=>({key:'c'+index,dataKey:'c'+index,title:headers.map((r:string[])=>r[index]).filter(Boolean).join(' / ')||'列 '+(index+1),width:165,cellRenderer:({rowData}:any)=>h('input',{class:'csv-cell',value:s.csv?.rows[rowData.index]?.[index]||'',disabled:s.csv?.editable===false||s.runtime.busy||!!s.pending||!!s.unknown,'aria-label':`第 ${rowData.index+1} 行第 ${index+1} 列`,'data-testid':'csv-cell','data-row':rowData.index,'data-column':index,onInput:(event:Event)=>w.editCsv(rowData.index,index,(event.target as HTMLInputElement).value)})}));});
const csvRows=computed(()=>(s.csv?.rows||[]).map((_:any,index:number)=>({id:index,index})));
const source=(name:string)=>s.params?.param_sources?.[name];
const defaultFor=(name:string)=>s.params?.thirdpart_defaults?.[name];
function changeBool(name:string,value:string){w.editParam(name,value);void w.saveParam(name);}
</script>
<template><div class="page-heading"><div><div class="eyebrow">PARAMETERS & VALIDATION</div><h1>核对实际运行参数</h1><p>XML 参数在完成编辑后自动保存；工参 CSV 需要明确保存。</p></div><el-tag v-if="s.job" effect="plain">{{s.job.schema}}</el-tag></div><section v-if="!s.job" class="card"><el-empty description="先加载运行 XML，或完成任务装配" :image-size="100"><el-button @click="s.stage=2" type="primary">选择配置</el-button></el-empty></section><template v-else><section class="card editor-card"><el-tabs v-model="s.editorTab"><el-tab-pane label="XML 参数 · 自动保存" name="xml"/><el-tab-pane label="工参 CSV · 手动保存" name="csv"/></el-tabs><template v-if="s.editorTab==='xml'"><div class="editor-toolbar"><el-select v-model="s.paramScope" :disabled="s.xmlDirty||!!s.pending" class="scope-select"><el-option value="current" label="当前功能推荐参数"/><el-option value="active" label="当前生效参数"/><el-option value="all" label="全部已识别参数"/></el-select><el-input v-model="s.paramSearch" placeholder="搜索参数名称、说明或值" clearable :disabled="s.xmlDirty||!!s.pending"/><span class="save-state" :class="{dirty:s.xmlDirty}">{{s.pending?'保存 / 读取中…':s.xmlDirty?'未保存草稿已保留':'自动保存 · 已同步'}}</span><el-button v-if="s.xmlDirty" @click="w.savePendingParams" :disabled="!!s.pending||s.runtime.busy||!!s.unknown">保存未保存参数</el-button><el-button @click="w.reloadParams" :disabled="!!s.pending||s.runtime.busy">{{s.xmlDirty?'放弃参数编辑':'重新加载'}}</el-button></div><div class="editor-file"><span>实际编辑</span><code>{{s.params?.file||s.job.schema}}</code><span>{{rowCount}} 项 / {{s.params?.counts?.total||'—'}} 项</span></div><div v-if="s.params?.profile" class="profile-note"><strong>{{s.params.profile.label||s.func}}</strong> {{s.params.profile.description}}<p v-if="!s.params.profile.reviewed">此功能范围尚未完整完成源码确认，请按全部参数核对。</p><p v-if="s.params.profile.source_review?.status==='changed'">当前项目源码存在差异，功能参数范围待复核。</p><p v-if="s.params.profile.missing_required?.length" class="warning-text">本功能需要但 XML 缺少：{{s.params.profile.missing_required.join('、')}}。不会自动补写字段。</p><p v-if="s.params.profile.scene_warning" class="warning-text">{{s.params.profile.scene_warning}}</p></div><el-empty v-if="!s.params" description="正在读取参数，或重新加载查看" :image-size="65"/><div v-for="group in groups" :key="group.group" class="parameter-group"><h3>{{group.group}}<span>{{group.rows.length}} 项</span></h3><div v-for="param in group.rows" :key="param.name" class="parameter-row" :class="{dirty:w.xml.drafts.has(param.name)}"><div class="parameter-name"><strong>{{param.label||param.name}}</strong><code>{{param.name}}</code><small>{{param.read_only?'只读':source(param.name)?.kind==='engineering_csv'?'工参 CSV 来源':param.usage?.active===false?'条件未启用':param.classification==='unclassified'?'适用范围待确认':param.usage?.required?'强制读取':'本功能参数'}}</small></div><div class="parameter-control"><el-input v-if="param.read_only" :model-value="String(s.paramValues[param.name]??'')" type="textarea" readonly :rows="2" :aria-label="param.name"/><el-select v-else-if="param.type==='bool'" :model-value="s.paramValues[param.name]" @change="changeBool(param.name,$event)" :disabled="s.runtime.busy||!!s.pending||!!s.unknown" :data-tag="param.name"><el-option v-if="!['true','false'].includes(s.paramValues[param.name])" :value="s.paramValues[param.name]" :label="'当前值：'+s.paramValues[param.name]"/><el-option value="true" label="true"/><el-option value="false" label="false"/></el-select><el-input v-else :model-value="s.paramValues[param.name]" @update:model-value="w.editParam(param.name,$event)" @change="w.saveParam(param.name)" :disabled="s.runtime.busy||!!s.pending||!!s.unknown||(source(param.name)?.kind==='engineering_csv'&&source(param.name)?.editable===false)" :data-tag="param.name" :placeholder="source(param.name)?.values?.length>1?'各小区值不同，填写后统一修改 CSV':''" :aria-label="param.name"/><el-button v-if="!param.read_only&&source(param.name)?.kind!=='engineering_csv'" text size="small" @click="w.restoreDefault(param.name)" :disabled="!defaultFor(param.name)?.available||s.xmlDirty||!!s.pending||s.runtime.busy" :title="defaultFor(param.name)?.reason||defaultFor(param.name)?.source||'项目样例未提供默认值'">ThirdPart 默认</el-button></div><div class="parameter-description"><p>{{param.desc}}</p><small v-if="source(param.name)?.kind==='engineering_csv'">实际修改 {{source(param.name).path}} 的 {{source(param.name).column}} 列；当前值 {{source(param.name).values?.join(' / ')}} 米。XML 仅作默认值。</small><small v-if="param.read_only">{{param.read_only_reason}}</small><small v-if="param.usage?.condition">条件：{{param.usage.condition}}</small><small v-if="param.usage?.source">源码依据：{{param.usage.source}}</small><small v-if="defaultFor(param.name)?.available">默认值来源：{{defaultFor(param.name).source}}</small></div></div></div><el-empty v-if="s.params&&!groups.length" description="没有符合当前筛选的参数" :image-size="65"/><section v-if="s.func==='predindoor'&&s.params?.indoor_building_export" class="indoor-panel"><h3>室内建筑 building.txt 源码导出</h3><p>{{s.params.indoor_building_export.supported?s.params.indoor_building_export.enabled?'源码开关已开启；若刚修改，请重新编译所选配置。':'源码开关未开启。启用会备份并修改当前项目源码，随后必须重新编译。':s.params.indoor_building_export.reason}}</p><div class="button-row"><el-button @click="w.reloadIndoor" :disabled="!!s.pending">重新检查</el-button><el-button type="warning" plain @click="w.enableIndoor" :disabled="!s.params.indoor_building_export.supported||s.params.indoor_building_export.enabled||!!s.pending||s.runtime.busy||s.xmlDirty||s.csvDirty">备份源码并启用导出</el-button><el-button @click="s.stage=1">前往重新编译</el-button></div></section></template><template v-else><el-alert v-if="s.unknown" title="之前的写入结果待核对。点击“放弃草稿并读取当前文件”只读取实际文件，读取成功后再清除本地草稿，不会重试写入。" type="warning" :closable="false" show-icon class="spaced-alert"/><div class="editor-toolbar"><div class="csv-path"><span>实际工参</span><code>{{s.csvPath||'当前 XML 未提供可用工参路径'}}</code></div><el-button @click="w.loadCsv()" data-testid="csv-load" :disabled="!s.csvPath||s.csvDirty||!!s.pending||s.runtime.busy">加载 CSV</el-button><el-button @click="w.loadCsv(true)" :disabled="!s.csvPath||!!s.pending||s.runtime.busy">{{s.unknown?'放弃草稿并读取当前文件':'放弃编辑并重新加载'}}</el-button><el-button type="primary" @click="w.saveCsv" data-testid="csv-save" :disabled="!s.csvDirty||s.csv?.editable===false||!!s.pending||s.runtime.busy||!!s.unknown">保存 CSV</el-button></div><div v-if="s.csv" class="csv-metadata"><el-tag :type="s.csvDirty?'warning':'success'">{{s.csvDirty?'CSV 有未保存编辑':'CSV 已同步'}}</el-tag><span>{{s.csv.encoding}} · {{s.csv.header_lines??s.csv.header_rows?.length}} 行表头 · {{s.csv.rows?.length}} 行数据</span><span v-if="s.csv.editable===false" class="warning-text">只读：{{s.csv.read_only_reason}}</span></div><div v-if="s.csv" class="csv-virtual-grid"><el-auto-resizer><template #default="{height,width}"><el-table-v2 :columns="columns" :data="csvRows" :width="width" :height="height" :row-height="36" :header-height="54" fixed/></template></el-auto-resizer></div><el-empty v-else description="点击加载 CSV 读取实际内容、编码与表头" :image-size="80"/><div v-if="s.csv" class="column-editor"><div><h3>整列修改与影响预览</h3><p>即将将选中列的 {{s.csv.rows?.filter((r:any)=>r.some(Boolean)).length||0}} 行有效工参统一设为指定值，确认后立即保存并备份。</p></div><el-select v-model="s.csvColumn" placeholder="明确选择列" :disabled="s.csvDirty||!!s.pending"><el-option v-for="(col,index) in columns" :key="col.key" :value="String(index)" :label="col.title"/></el-select><el-input v-model="s.csvValue" placeholder="整列目标值" :disabled="s.csvDirty||!!s.pending"/><el-popconfirm title="确认统一修改此列并立即保存？原文件将备份。" @confirm="w.setColumn"><template #reference><el-button type="warning" plain :disabled="!s.csvColumn||s.csvDirty||!!s.pending||s.runtime.busy||s.csv.editable===false">确认整列写入</el-button></template></el-popconfirm></div></template></section><section class="card"><div class="card-heading"><span class="card-icon teal">✓</span><div><h2>运行前检查</h2><p>只读核验实际 XML、CSV、地图、天线、模型及路测依赖</p></div><el-button type="primary" plain data-testid="preflight" @click="w.preflight" :disabled="!s.job||s.xmlDirty||s.csvDirty||!!s.pending||s.runtime.busy">检查当前配置</el-button></div><template v-if="s.preflight"><el-alert :type="s.preflight.ok?'success':'warning'" :title="s.preflight.ok?'当前版本检查通过':'检查未通过或存在未确认项'" :closable="false" show-icon/><el-table :data="s.preflight.issues||[]" empty-text="未发现阻断问题"><el-table-column label="等级" width="100"><template #default="{row}"><el-tag :type="row.severity==='error'?'danger':'warning'">{{row.severity==='error'?'阻断':'提示'}}</el-tag></template></el-table-column><el-table-column prop="message" label="检查结论"/><el-table-column prop="field" label="字段" width="180"/><el-table-column prop="path" label="关联路径"/></el-table><JsonReport :data="s.preflight" title="查看检查上下文与全部结论"/></template><div v-else class="empty-inline">尚未检查。参数内容保存后，之前的检查会失效。</div></section></template></template>
